def outer(nums: list[int]) -> int:
    best = 0

    def helper(i: int) -> None:
        nonlocal best              # without this, 'best = ...' makes a LOCAL
        best = max(best, nums[i])

    for i in range(len(nums)):
        helper(i)
    return best

# Mutable default trap — the list is created once, at definition time.
def bad(x, acc=[]):               # DON'T
    acc.append(x)
    return acc

def good(x, acc=None):            # DO
    if acc is None:
        acc = []
    acc.append(x)
    return acc

# Memoisation for free.
from functools import cache

@cache
def fib(n: int) -> int:
    return n if n <= 1 else fib(n - 1) + fib(n - 2)
